// Reproduce the bundled map engine from the existing website's pinned Leaflet.
// No runtime CDN script, build-time download or native dependency is introduced.
import { readFile, writeFile } from "node:fs/promises";
const source = new URL("../../asha-saath-lovable/node_modules/leaflet/", import.meta.url);
const packageInfo = JSON.parse(await readFile(new URL("package.json", source), "utf8"));
if (packageInfo.version !== "1.9.4") throw new Error("Review a Leaflet upgrade before rebundling.");
const license = await readFile(new URL("LICENSE", source), "utf8");
const js = (await readFile(new URL("dist/leaflet.js", source), "utf8"))
  .replace(/\/\/# sourceMappingURL=.*$/gm, "");
// Only DivIcons are used. Unused default marker/layer PNGs are not shipped.
const css = (await readFile(new URL("dist/leaflet.css", source), "utf8"))
  .replace(/url\([^)]*\)/g, "none");
const text = "// Generated by scripts/bundle-leaflet.mjs; Leaflet 1.9.4 BSD-2-Clause.\n" +
  "// Original license is reproduced in each generated map document.\n" +
  `export const leafletLicense = ${JSON.stringify(license)};\n` +
  `export const leafletJs = ${JSON.stringify(js)};\n` +
  `export const leafletCss = ${JSON.stringify(css)};\n`;
await writeFile(new URL("../src/lib/leaflet-bundle.ts", import.meta.url), text);
console.log("Bundled Leaflet 1.9.4 JavaScript/CSS with BSD license; no runtime CDN.");
